/* a button that opens whatever the admin chose */
function lBtn(label,link,cls,icon){link=link||'signup';const inner=`${icon&&icon!=='arrow'?ic(icon,18):''}${esc(label)}${icon==='arrow'?' '+ic('arrow',18):''}`;
  if(/^https?:\/\//.test(link))return `<a class="${cls}" href="${esc(link)}" target="_blank" rel="noopener">${inner}</a>`;
  const a={signup:'data-act="ctaManage"',demo:'data-act="lDemo"',enquiry:'data-act="lEnq"',how:'data-act="lGo" data-to="how"',contact:'data-act="lGo" data-to="contact"',blog:'data-act="lGo" data-to="blog"',home:'data-act="lGo" data-to="home"'}[link]||'data-act="ctaManage"';
  return `<button type="button" class="${cls}" ${a}>${inner}</button>`}
