function webRx(fk){const lg=UILANGS.some(x=>x[0]===UIL)?UIL:'en',tl=v=>lg==='en'?v:translit(v,lg),A=S.accounts&&S.accounts[0];
  const ev={id:'__web',acc:A?A.id:'',no:'EV002',name:WEBEVN[lg]||WEBEVN.en,type:WEBTYP[lg]||'Wedding',date:'2026-08-02',start:'18:00',end:'22:00',venue:tl('Annai Mahal'),address:tl('Anna Nagar, Madurai'),organizer:tl('Ramesh Kumar'),logo:SH('couple'),logoT:1,lang:lg,rfmt:fk,status:'active',notify:{}};
  const u={id:'__wu',name:tl('Ravi'),role:'collector',acc:ev.acc};
  const m={id:'__wm',event_id:'__web',code:'EV002/014',c:{name:'Murugesan',place:'Tambaram',relationship:'Uncle (Mama)',mobile:'984** **301'},amount:10001,kind:'cash',mode:'cash',status:'verified',date:'2026-08-02',time:'18:40',collected_by:'__wu',created_at:'2026-08-02T18:40:00'};
  S.events.push(ev);S.users.push(u);let h='';try{h=rcptHtml(m,lg,fk)}catch(e){h=''}finally{S.events.splice(S.events.indexOf(ev),1);S.users.splice(S.users.indexOf(u),1)}return h}
const rxLive=(k,cls='')=>`<div class="rx-live ${cls}" aria-label="Sample receipt" data-noi18n>${webRx(String(k).replace(/^rx-/,''))}</div>`;
const dvAny=k=>!k?'':k.startsWith('rx-')?rxLive(k,'shot'):k.startsWith('an-')?dvAndroid(k):k.startsWith('ip-')?dvPhone(k):k.startsWith('desk-')?dvLaptop(k):`<img class="ls-shot" src="${SH(k)}" alt="">`;
function lArt(x){const b='<span class="ls-blob"></span>';
  switch(x.layout){
   case 'people':return `<div class="ls-art couple">${b}${wim(x.img)?`<img class="ls-couple" src="${wim(x.img)}" alt="">`:''}${x.shot?`<div class="ls-dev">${dvAny(x.shot)}</div>`:''}</div>`;
   case 'two':return `<div class="ls-art two">${b}${wim(x.img)?`<img class="t1" src="${wim(x.img)}" alt="">`:''}${wim(x.img2)?`<img class="t2" src="${wim(x.img2)}" alt="">`:''}</div>`;
   case 'receipts':return `<div class="ls-art rxs">${b}${rxLive(x.shot&&x.shot.startsWith('rx')?x.shot:'rx-royal','r1')}${rxLive(x.shot2||'rx-temple','r2')}</div>`;
   case 'scan':return lScanArt();
   case 'phone':if(x.shot==='an-qrpage')return lScanArt();return `<div class="ls-art one">${b}<div class="ls-dev">${dvAny(x.shot||'ip-receive')}</div></div>`;
   case 'laptop':return `<div class="ls-art one">${b}<div class="ls-lap">${dvAny(x.shot||'desk-event')}</div></div>`;
   default:return `<div class="ls-art pic">${b}${wim(x.img)?`<img class="ls-pic" src="${wim(x.img)}" alt="">`:''}</div>`}}
function lSlider(id,list,kind){if(!list.length)return '';const n=list.length;
  const body=list.map((x,i)=>`<div class="lp-slide ${i?'':'on'}" aria-hidden="${!!i}">${kind==='offer'?lOfferCard(x):`<div class="lp-copy"><span class="lp-tag">${esc(x.tag||'')}</span><h${id==='lpSlider'?1:2} class="lp-h">${esc(x.title)}</h${id==='lpSlider'?1:2}>${x.sub?`<p>${esc(x.sub)}</p>`:''}<div class="lp-row">${x.btn===''?'':lBtn(x.btn||'Start free',x.link,'btn btn-primary','arrow')}${x.link==='demo'?'':`<button class="btn btn-ghost" data-act="lDemo">${ic('cal',18)}Book a demo</button>`}</div></div>${lArt(x)}`}</div>`).join('');
  return `<div class="lp-sw ${kind==='offer'?'lp-osw':''}" data-sw><div class="lp-slider ${kind==='offer'?'lp-oslider':''} ${kind==='page'?'lp-pslider':''}" id="${id}" data-i="0" aria-roledescription="carousel">${body}${n>1?`<button class="lp-arr l" data-act="lSl" data-d="-1" aria-label="Previous slide">${ic('back',18)}</button><button class="lp-arr r" data-act="lSl" data-d="1" aria-label="Next slide">${ic('arrow',18)}</button>`:''}</div>${n>1?`<div class="lp-dots">${list.map((_,i)=>`<button aria-label="Slide ${i+1}" aria-current="${!i}" data-act="lSlGo" data-v="${i}"></button>`).join('')}</div>`:''}</div>`}
function lOfferCard(o){return `<div class="lp-offer"><div class="lp-oin">${wim(o.img)?`<img class="lp-ocouple" src="${wim(o.img)}" alt="">`:'<span></span>'}<div class="lp-ocopy">${o.tag?`<span class="ta">${esc(o.tag)}</span>`:''}<h2>${esc(o.title)}</h2>${o.sub?`<p>${esc(o.sub)}</p>`:''}${lBtn(o.btn||'Start free',o.link,'btn btn-primary btn-lg','arrow')}</div>${o.price?`<div class="lp-oprice"><b>${esc(o.price)}</b><span>${esc(o.note||'')}</span></div>`:''}</div></div>`}
